from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and
                            p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            yield color, cells


def _elbow(cells):
    """Return the perpendicular arm directions if cells are one exact corner L."""
    if len(cells) < 3:
        return None
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    corners = [
        ((r0, c0), ((0, 1), (1, 0))),
        ((r0, c1), ((0, -1), (1, 0))),
        ((r1, c0), ((0, 1), (-1, 0))),
        ((r1, c1), ((0, -1), (-1, 0))),
    ]
    for (r, c), (d1, d2) in corners:
        arm1 = {(r + k*d1[0], c + k*d1[1]) for k in range(max(r1-r0, c1-c0)+1)}
        arm2 = {(r + k*d2[0], c + k*d2[1]) for k in range(max(r1-r0, c1-c0)+1)}
        arms = (arm1 | arm2) & {(y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)}
        if (r, c) in cells and cells <= arms and
                any((r + d1[0], c + d1[1]) in cells for _ in [0]) and
                any((r + d2[0], c + d2[1]) in cells for _ in [0]):
            # Return vectors pointing away from the elbow, not their length.
            return d1, d2
    return None


def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = list(_components(grid, bg))
    marker = None
    # A distinct-colored L gives the orientation and replacement color.
    for color, cells in comps:
        if color != 7:
            orient = _elbow(cells)
            if orient is not None:
                marker = (color, orient)
                break
    if marker is None:
        return out
    new_color, orient = marker
    for color, cells in comps:
        if color != 7:
            continue
        for r, c in cells:
            if all((r + dy, c + dx) in cells for dy, dx in orient):
                for y, x in cells:
                    out[y][x] = new_color
                return out
    return out

