def _l_orientation(cells):
    """Get the two perpendicular arms from an exact, one-cell-thick L."""
    if len(cells) < 3:
        return None
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    corners = [
        ((r0, c0), (0, 1), (1, 0)),
        ((r0, c1), (0, -1), (1, 0)),
        ((r1, c0), (0, 1), (-1, 0)),
        ((r1, c1), (0, -1), (-1, 0)),
    ]
    for (r, c), d1, d2 in corners:
        arm1 = {(r + k*d1[0], c + k*d1[1]) for k in range(max(r1-r0, c1-c0)+1)}
        arm2 = {(r + k*d2[0], c + k*d2[1]) for k in range(max(r1-r0, c1-c0)+1)}
        if cells == arm1 | arm2:
            return d1, d2
    return None


