def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    # The large monochrome L is a color-and-direction pointer. Its inward
    # elbow selects the nearest non-background object in the open quadrant.
    markers = []
    for color, cells in comps:
        if len(cells) < 3:
            continue
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        for (r,c), d1,d2 in [((r0,c0),(0,1),(1,0)), ((r0,c1),(0,-1),(1,0)),
                             ((r1,c0),(0,1),(-1,0)), ((r1,c1),(0,-1),(-1,0))]:
            a={(r+k*d1[0], c+k*d1[1]) for k in range((r1-r0 if d1[0] else c1-c0)+1)}
            b={(r+k*d2[0], c+k*d2[1]) for k in range((r1-r0 if d2[0] else c1-c0)+1)}
            if cells == a | b and (r1-r0 > 2 or c1-c0 > 2):
                markers.append((color,cells,(r,c),d1,d2))
                break
    if not markers:
        return [row[:] for row in grid]
    color, mark, (er,ec), d1,d2 = max(markers, key=lambda m: len(m[1]))
    # The desired region is diagonally opposite the two arms.
    sy, sx = -d1[0], -d2[1]
    candidates=[]
    for col,cells in comps:
        if cells == mark: continue
        cy=sum(r for r,c in cells)/len(cells); cx=sum(c for r,c in cells)/len(cells)
        if (cy-er)*sy > 0 and (cx-ec)*sx > 0:
            # nearest component in the opposite quadrant
            dist=min((r-er)**2+(c-ec)**2 for r,c in cells)
            candidates.append((dist, col, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda v:v[0])
    out=[row[:] for row in grid]
    for r,c in target:
        out[r][c]=color
    return out

