def l_marker(cells):
    if len(cells) < 3:
        return None
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    for (r, c), d1, d2 in [((r0,c0),(0,1),(1,0)), ((r0,c1),(0,-1),(1,0)),
                            ((r1,c0),(0,1),(-1,0)), ((r1,c1),(0,-1),(-1,0))]:
        a = {(r+k*d1[0], c+k*d1[1]) for k in range((r1-r0 if d1[0] else c1-c0)+1)}
        b = {(r+k*d2[0], c+k*d2[1]) for k in range((r1-r0 if d2[0] else c1-c0)+1)}
        if cells == a | b:
            return (r,c), d1, d2
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = components(grid, bg)
    markers = [(color, cells, l_marker(cells)) for color,cells in comps if l_marker(cells)]
    if not markers:
        return [row[:] for row in grid]
    marker_color, marker_cells, (corner, d1, d2) = max(markers, key=lambda x: len(x[1]))
    er, ec = corner
    candidates = []
    for color, cells in comps:
        if cells == marker_cells:
            continue
        cy = sum(r for r,c in cells) / len(cells)
        cx = sum(c for r,c in cells) / len(cells)
        if (cy-er)*(-d1[0]) > 0 and (cx-ec)*(-d2[1]) > 0:
            dist = min((r-er)**2 + (c-ec)**2 for r,c in cells)
            candidates.append((dist, cells))
    if not candidates:
        return [row[:] for row in grid]
    target = min(candidates, key=lambda x: x[0])[1]
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = marker_color
    return out

