def _lshape(cells):
    if len(cells)<3:return None
    r0,r1=min(y for y,x in cells),max(y for y,x in cells)
    c0,c1=min(x for y,x in cells),max(x for y,x in cells)
    for (r,c),a,b in [((r0,c0),(0,1),(1,0)),((r0,c1),(0,-1),(1,0)),((r1,c0),(0,1),(-1,0)),((r1,c1),(0,-1),(-1,0))]:
        aa={(r+k*a[0],c+k*a[1]) for k in range((c1-c0 if a[1] else r1-r0)+1)}
        bb={(r+k*b[0],c+k*b[1]) for k in range((c1-c0 if b[1] else r1-r0)+1)}
        if cells==aa|bb:return (r,c),a,b
    return None

