    vr=a if a[0] else b; hr=a if a[1] else b
    sr,sc=-vr[0],-hr[1]
    candidates=[]
    for co,cells in comps:
        if cells==marker:continue
        cy=sum(y for y,x in cells)/len(cells); cx=sum(x for y,x in cells)/len(cells)
        if (cy-r)*sr>0 and (cx-c)*sc>0:
            candidates.append((abs(cy-r)+abs(cx-c),co,cells))
