        # The marker is an L made of two complete adjoining bbox sides.
        for er in (r0, r1):
            for ec in (c0, c1):
                horiz = {(er, c) for c in range(c0, c1 + 1)}
                vert = {(r, ec) for r in range(r0, r1 + 1)}
                if s == horiz | vert:
                    dr = 1 if er == r0 else -1
                    dc = 1 if ec == c0 else -1
                    markers.append((idx, color, (er, ec), dr, dc))
