        return out
    # The L's open corner points to the opposite diagonal quadrant.
    idx, marker_color, (er, ec), dr, dc = max(markers, key=lambda m: len(comps[m[0]][1]))
    candidates = []
    for j, (color, cells) in enumerate(comps):
        if j == idx:
            continue
        # Component center must lie beyond the elbow, opposite both L arms.
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr - er) * dr < 0 and (cc - ec) * dc < 0:
            distance = min(abs(r-er) + abs(c-ec) for r, c in cells)
            candidates.append((distance, j, color))
    if candidates:
        _, target_idx, _ = min(candidates)
        target_color, cells = comps[target_idx]
        for r, c in cells:
            out[r][c] = marker_color
    return out

