        for sample_color, sample in samples:
            wanted = _shape(sample)
            copies = [(color,cells) for color,cells in objs
                      if cells != marker and cells != sample and _shape(cells) == wanted]
            if copies:
                # Recolor the matching copy outside the marker's cavity.
                for _, cells in copies:
