def _segments(edge, bg):
    out = []
    i = 0
    while i < len(edge):
        if edge[i] == bg:
            i += 1
            continue
        color = edge[i]
        j = i
        while j + 1 < len(edge) and edge[j + 1] == color:
            j += 1
        out.append((i, j, color))
        i = j + 1
    return out


