            for offset in range(length):
                r = rstart + offset
                # An interior colored mark on a right-bar row launches a
                # ray toward the right edge; its paired left-bar row is filled
                # across the grid in that mark's color.
                marks = [c for c in range(1, w - 1) if grid[r][c] != bg]
                for c in marks:
                    ink = grid[r][c]
                    out[r][c] = 4
                    for x in range(c + 1, w - 1):
                        if grid[r][x] == bg:
                            out[r][x] = ink
                        else:
                            break
                    paired_r = lstart + offset
                    for x in range(1, w):
                        if grid[paired_r][x] != bg:
                            break
                        out[paired_r][x] = ink
    return out

def transform(grid):
    # Shift colors down one step, with color 4 mapping to the empty color 0.
    return [[0 if value == 4 else value - 1 for value in row] for row in grid]

def transform(grid):
    """Normalize the lower of the two binary-symbol colors to 0 and the higher to 2."""
    colors = sorted({value for row in grid for value in row})
    if len(colors) != 2:
        raise ValueError("expected exactly two input colors")
    low, high = colors
    mapping = {low: 0, high: 2}
    return [[mapping[value] for value in row] for row in grid]

def transform(grid):
    """The symbol 5 is recolored to the other palette color; the other color becomes 0."""
    colors = {value for row in grid for value in row}
    if len(colors) != 2 or 5 not in colors:
        raise ValueError("expected a two-color grid containing color 5")
    replacement = next(color for color in colors if color != 5)
    return [[replacement if value == 5 else 0 for value in row] for row in grid]

